import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import {
  Box, Typography, Paper, Grid, TextField, Button, FormControl, InputLabel,
  Select, MenuItem, Card, CardContent, Avatar, Chip, Alert, CircularProgress,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
  IconButton, Dialog, DialogTitle, DialogContent, DialogActions, Divider,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EventBusyIcon from '@mui/icons-material/EventBusy';
import PersonOffIcon from '@mui/icons-material/PersonOff';
import CardGiftcardIcon from '@mui/icons-material/CardGiftcard';
import PaymentsIcon from '@mui/icons-material/Payments';
import MoneyOffIcon from '@mui/icons-material/MoneyOff';
import { formatPersianNumber, toPersianDigits } from '../core/utils/numberUtils';
import { toJalali } from '../core/utils/dateUtils';
import JalaliDatePicker from '../core/components/ui/JalaliDatePicker';

const TYPE_CONFIG = {
  leave: { label: 'مرخصی', icon: <EventBusyIcon />, color: '#6366f1', usesQuantity: true, quantityLabel: 'روز' },
  absence: { label: 'غیبت', icon: <PersonOffIcon />, color: '#ef4444', usesQuantity: true, quantityLabel: 'روز' },
  benefit: { label: 'مزایای رفاهی', icon: <CardGiftcardIcon />, color: '#10b981', usesQuantity: true, quantityLabel: 'تعداد' },
  salary: { label: 'حقوق پرداختی', icon: <PaymentsIcon />, color: '#f59e0b', usesQuantity: false, quantityLabel: '' },
  deduction: { label: 'کسورات', icon: <MoneyOffIcon />, color: '#8b5cf6', usesQuantity: false, quantityLabel: '' },
};

const DataEntryPage = () => {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ transaction_type: '', title: '', amount: '', quantity: '', date: '', employee: '', description: '' });
  const [error, setError] = useState('');

  const { data: employees } = useQuery({
    queryKey: ['emp-dropdown'],
    queryFn: () => axiosInstance.get('/employees/', { params: { page_size: 500 } }).then(r => r.data.results || r.data),
  });

  const { data: transactions } = useQuery({
    queryKey: ['transactions'],
    queryFn: () => axiosInstance.get('/transactions/').then(r => r.data),
  });

  const saveMutation = useMutation({
    mutationFn: (payload) => axiosInstance.post('/transactions/', payload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['transactions'] });
      queryClient.invalidateQueries({ queryKey: ['transactions-summary'] });
      setOpen(false);
      setForm({ transaction_type: '', title: '', amount: '', quantity: '', date: '', employee: '', description: '' });
      setError('');
    },
    onError: (e) => setError(e.response?.data?.error || 'خطا در ذخیره'),
  });

  const handleSave = () => {
    if (!form.employee || !form.transaction_type || !form.date) {
      setError('پرسنل، نوع تراکنش و تاریخ الزامی است');
      return;
    }
    const payload = { ...form };
    payload.amount = form.amount ? Number(form.amount) : 0;
    payload.quantity = form.quantity ? Number(form.quantity) : 0;
    saveMutation.mutate(payload);
  };

  const selectedType = TYPE_CONFIG[form.transaction_type];

  const items = Array.isArray(transactions) ? transactions : transactions?.results || [];

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          <Typography variant="h4" fontWeight={800}>ورود اطلاعات</Typography>
          <Typography variant="body2" color="textSecondary">ثبت مرخصی، غیبت، مزایا، حقوق و کسورات پرسنل</Typography>
        </Box>
        <Button variant="contained" startIcon={<AddIcon />} onClick={() => setOpen(true)}>افزودن تراکنش</Button>
      </Box>

      <TableContainer component={Paper}>
        {!items.length ? (
          <Box sx={{ p: 4, textAlign: 'center' }}><Typography color="textSecondary">تراکنشی ثبت نشده است</Typography></Box>
        ) : (
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 700 }}>پرسنل</TableCell>
                <TableCell sx={{ fontWeight: 700 }}>نوع</TableCell>
                <TableCell sx={{ fontWeight: 700 }}>عنوان</TableCell>
                <TableCell sx={{ fontWeight: 700 }}>مبلغ (ریال)</TableCell>
                <TableCell sx={{ fontWeight: 700 }}>مقدار</TableCell>
                <TableCell sx={{ fontWeight: 700 }}>تاریخ</TableCell>
                <TableCell width={60} sx={{ fontWeight: 700 }}>حذف</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {items.map(tx => {
                const cfg = TYPE_CONFIG[tx.transaction_type] || { label: tx.transaction_type_display, color: '#999' };
                return (
                  <TableRow key={tx.id} hover>
                    <TableCell>{tx.employee_name}</TableCell>
                    <TableCell>
                      <Chip size="small" label={tx.transaction_type_display} sx={{ color: cfg.color, borderColor: cfg.color }} variant="outlined" />
                    </TableCell>
                    <TableCell>{tx.title || '—'}</TableCell>
                    <TableCell>{tx.amount ? formatPersianNumber(tx.amount) : '—'}</TableCell>
                    <TableCell>{tx.quantity ? formatPersianNumber(tx.quantity) : '—'}</TableCell>
                    <TableCell>{toJalali(tx.date)}</TableCell>
                    <TableCell>
                      <IconButton size="small" color="error"
                        onClick={() => axiosInstance.delete(`/transactions/${tx.id}/`).then(() => queryClient.invalidateQueries({ queryKey: ['transactions'] }))}>
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        )}
      </TableContainer>

      {/* Add/Edit dialog */}
      <Dialog open={open} onClose={() => setOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>افزودن تراکنش</DialogTitle>
        <DialogContent>
          {error && <Alert severity="error" sx={{ mb: 1 }}>{error}</Alert>}

          <FormControl fullWidth size="small" sx={{ mt: 1.5 }}>
            <InputLabel>پرسنل</InputLabel>
            <Select value={form.employee} label="پرسنل" onChange={e => setForm(p => ({ ...p, employee: e.target.value }))}>
              {Array.isArray(employees) && employees.map(emp => (
                <MenuItem key={emp.id} value={emp.id}>{emp.full_name} ({emp.employee_id})</MenuItem>
              ))}
            </Select>
          </FormControl>

          <FormControl fullWidth size="small" sx={{ mt: 1.5 }}>
            <InputLabel>نوع تراکنش</InputLabel>
            <Select value={form.transaction_type} label="نوع تراکنش" onChange={e => setForm(p => ({ ...p, transaction_type: e.target.value }))}>
              {Object.entries(TYPE_CONFIG).map(([key, cfg]) => (
                <MenuItem key={key} value={key}>{cfg.label}</MenuItem>
              ))}
            </Select>
          </FormControl>

          <TextField fullWidth size="small" label="عنوان (اختیاری)" value={form.title}
            onChange={e => setForm(p => ({ ...p, title: e.target.value }))} sx={{ mt: 1.5 }} />

          <Grid container spacing={1.5} sx={{ mt: 0.5 }}>
            <Grid item xs={6}>
              <TextField fullWidth size="small" label="مبلغ (ریال)" type="number" value={form.amount}
                onChange={e => setForm(p => ({ ...p, amount: e.target.value }))
              } />
            </Grid>
            {selectedType?.usesQuantity && (
              <Grid item xs={6}>
                <TextField fullWidth size="small" label={selectedType.quantityLabel} type="number" value={form.quantity}
                  onChange={e => setForm(p => ({ ...p, quantity: e.target.value }))} />
              </Grid>
            )}
          </Grid>

          <Box sx={{ mt: 1.5 }}>
            <JalaliDatePicker fullWidth label="تاریخ" value={form.date}
              onChange={gregorian => setForm(p => ({ ...p, date: gregorian }))} />
          </Box>

          <TextField fullWidth size="small" label="توضیحات" multiline rows={2} value={form.description}
            onChange={e => setForm(p => ({ ...p, description: e.target.value }))} sx={{ mt: 1.5 }} />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>انصراف</Button>
          <Button variant="contained" onClick={handleSave} disabled={saveMutation.isLoading}>
            {saveMutation.isLoading ? <CircularProgress size={20} /> : 'ذخیره'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default DataEntryPage;
